WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) AS prev_paid_at FROM payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessions_payments AS (SELECT id, order_id, paid_at, status, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT s.id, s.order_id, (SELECT SUM(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS sum_payment_amount FROM sessions_payments s ORDER BY id DESC NULLS FIRST
